import { NextResponse, type NextRequest } from 'next/server';
import type { EmailOtpType } from '@supabase/supabase-js';
import { createClient } from '@/lib/supabase/server';

/** Links generated by the studio (portal invites): ?token_hash=…&type=invite|magiclink */
export async function GET(req: NextRequest) {
  const url = new URL(req.url);
  const token_hash = url.searchParams.get('token_hash');
  const type = (url.searchParams.get('type') || 'magiclink') as EmailOtpType;
  const nextRaw = url.searchParams.get('next') || '/app';
  const next = nextRaw.startsWith('/') && !nextRaw.startsWith('//') ? nextRaw : '/app';
  if (token_hash) {
    const sb = await createClient();
    const { error } = await sb.auth.verifyOtp({ type, token_hash });
    if (error) {
      const login = next.startsWith('/p/') ? next.split('/').slice(0, 3).join('/') + '/login' : '/login';
      return NextResponse.redirect(new URL(`${login}?err=${encodeURIComponent('That link has expired or was already used. Request a new one below.')}`, url.origin));
    }
  }
  return NextResponse.redirect(new URL(next, url.origin));
}
